{
  "domain objects": [
    {
      "name": "Cinema Manager",
      "description": "Oversees film scheduling, staffing approvals, and performance data."
    },
    {
      "name": "Auditorium",
      "description": "A theater room where films are shown.",
      "attributes": [
        "Film",
        "Equipment"
      ]
    },
    {
      "name": "Screening",
      "description": "A scheduled showing of a film.",
      "attributes": [
        "Film",
        "Attendance"
      ]
    },
    {
      "name": "Film",
      "description": "A movie selected and scheduled for screening."
    },
    {
      "name": "Attendance",
      "description": "Recorded number of visitors for a screening."
    },
    {
      "name": "Equipment",
      "description": "Technical hardware supporting film projection."
    },
    {
      "name": "Staffing Plan",
      "description": "Assignment of staff to stations for a shift.",
      "attributes": [
        "Ticket Station",
        "Concession Station"
      ]
    },
    {
      "name": "Shift Supervisor",
      "description": "Prepares screening schedules and assigns staff."
