      ]
    },
    {
      "name": "Ticketing Clerk",
      "description": "Sells tickets and processes refunds."
    },
    {
      "name": "Operational Issue Report",
      "description": "A record of problems encountered during a shift."
    },
    {
      "name": "Projectionist",
      "description": "Runs the projection system and ensures smooth screenings."
    },
    {
      "name": "Projection System",
      "description": "The system used to load and project films.",
      "attributes": [
        "Film"
      ]
    },
    {
      "name": "Equipment Malfunction Report",
      "description": "A report documenting faulty equipment."
    },
    {
      "name": "Concession Station",
      "description": "Workstation for selling snacks.",
      "attributes": [
        "Concession Clerk"
      ]
    },
    {
      "name": "Concession Clerk",
      "description": "Handles snack sales and tracks inventory."
    },
    {
      "name": "Snack Inventory",
      "description": "Stock of snacks available at concession."
    },
    {
      "name": "Shortage Report",
      "description": "A record of items needing restocking."
    },
    {
      "name": "Procurement Team",
      "description": "Handles ordering supplies for the cinema."
    },
    {
      "name": "Ticket",
